solutionCode:
pub struct Ponto {
    pub x: i32,
    pub y: i32,
}

impl Ponto {
    pub fn new(x: i32, y: i32) -> Ponto {
        Ponto { x: x, y: y }
    }

    pub fn escalado(&self, k: i32) -> Ponto {
        Ponto { x: self.x * k, y: self.y * k }
    }
}

testsCode:
use desafio::Ponto;

#[test]
fn testa_o_x_do_construtor_dois_por_tres() {
    assert_eq!(Ponto::new(2, 3).x, 2);
}

#[test]
fn testa_o_y_do_construtor_negativo_um_por_quatro() {
    assert_eq!(Ponto::new(-1, 4).y, 4);
}

#[test]
fn testa_o_x_da_peca_escalada() {
    assert_eq!(Ponto::new(2, 3).escalado(3).x, 6);
}

#[test]
fn testa_o_y_da_peca_escalada_por_dois() {
    assert_eq!(Ponto::new(-1, 4).escalado(2).y, 8);
}
